+          gradient: "linear-gradient(135deg, #f3e3c9 0%, #9b6415 100%)"
+        }
+      ];
+
+      function ButtonLink({ href, label, variant = "" }) {
+        return `<a class="button ${variant}" href="${href}">${label}</a>`;
+      }
+
+      function Header() {
+        const navItems = ["New Arrivals", "Home", "Style", "Stories"];
+        return `
+          <header class="site-header">
+            <div class="header-inner">
+              <a class="brand" href="#" aria-label="North & Finch home">
+                <span class="brand-mark" aria-hidden="true">N&F</span>
+                <span>North & Finch</span>
+              </a>
+              <nav class="site-nav" aria-label="Primary navigation">
+                <ul class="nav-list">
+                  ${navItems.map((item) => `
+                    <li><a class="nav-link" href="#${item.toLowerCase().replaceAll(" ", "-")}">${item}</a></li>
+                  `).join("")}
+                </ul>
+              </nav>
+              <nav aria-label="Shopping links">
+                <ul class="utility-list">
+                  <li><a class="utility-link" href="#search">Search</a></li>
+                  <li><a class="utility-link" href="#cart">Cart (0)</a></li>
+                </ul>
+              </nav>
+            </div>
+          </header>
+        `;
+      }
+
+      function Hero() {
+        return `
+          <section class="hero container" aria-labelledby="hero-title">
+            <div class="hero-grid">
+              <div class="hero-copy">
+                <p class="eyebrow">Spring collection 2026</p>
+                <h1 id="hero-title">Design-led essentials for everyday living.</h1>
+                <p class="muted">
+                  Shop considered home goods, wardrobe staples, and travel-ready accessories
+                  from a retail brand focused on longevity, comfort, and calm.
+                </p>
+                <div class="hero-actions">
+                  ${ButtonLink({ href: "#featured-products", label: "Shop featured products" })}
+                  ${ButtonLink({ href: "#editorial", label: "Read the edit", variant: "button-secondary" })}
+                </div>
+              </div>
+              <div class="hero-panel" aria-label="Collection highlights">
+                <article class="feature-card">
+                  <div class="product-visual" aria-hidden="true"></div>
+                  <div class="feature-card-content">
+                    <span class="tag">Limited capsule</span>
+                    <div>
+                      <h2>Quiet luxury, lower impact.</h2>
+                      <p class="muted">Natural fibers, modular silhouettes, and packaging designed for reuse.</p>
+                    </div>
+                  </div>
+                </article>
+                <aside class="mini-card" aria-label="Store benefits">
+                  <p class="eyebrow">Why shoppers return</p>
+                  <div class="stats">
+                    <div class="stat"><strong>4.9</strong><span class="muted">Average rating</span></div>
+                    <div class="stat"><strong>2-day</strong><span class="muted">Express delivery</span></div>
+                    <div class="stat"><strong>365</strong><span class="muted">Day returns</span></div>
+                  </div>
+                </aside>
+              </div>
+            </div>
+          </section>
+        `;
+      }
+
+      function ProductCard(product) {
+        return `
+          <article class="product-card">
+            <div class="product-media" style="background: ${product.gradient};">
+              <div class="product-shape" style="--product-gradient: ${product.gradient};" aria-hidden="true"></div>
+            </div>
+            <div class="product-body">
+              <div class="product-meta">
+                <span>${product.category}</span>
+                <span class="tag">${product.badge}</span>
+              </div>
+              <h3>${product.name}</h3>
+              <p class="muted">Refined proportions, durable materials, and a soft modern finish.</p>
+              <div class="price-row">
+                <span class="price">${product.price}</span>
+                <span class="old-price">${product.oldPrice}</span>
+              </div>
+              <button class="button" type="button" aria-label="Add to cart: ${product.name}">Add to cart</button>
+            </div>
+          </article>
+        `;
+      }
+
+      function FeaturedProducts() {
+        return `
+          <section class="section container" id="featured-products" aria-labelledby="featured-title">
+            <div class="section-heading">
+              <div>
+                <p class="section-kicker">Featured products</p>
+                <h2 id="featured-title">Fresh picks with staying power.</h2>
+              </div>
+              ${ButtonLink({ href: "#new-arrivals", label: "View all new arrivals", variant: "button-secondary" })}
+            </div>
+            <div class="product-grid">
+              ${products.map(ProductCard).join("")}
+            </div>
+          </section>
+        `;
+      }
+
+      function Deals() {
+        return `
+          <section class="section container" id="deals" aria-labelledby="deals-title">
+            <div class="deals-band">
+              <div class="deal-hero">
+                <div>
+                  <p class="section-kicker">Weekend deals</p>
+                  <h2 id="deals-title">Save up to 30% on curated seasonal edits.</h2>
+                  <p class="muted">Offer ends Sunday at midnight. Prices update automatically at checkout.</p>
+                </div>
+                ${ButtonLink({ href: "#featured-products", label: "Shop the sale" })}
+              </div>
+              <div class="deal-list" aria-label="Current deal categories">
+                ${deals.map((deal) => `
+                  <article class="deal-item">
+                    <strong class="deal-percent">${deal.percent}</strong>
+                    <div>
+                      <h3>${deal.title}</h3>
+                      <p class="muted">${deal.copy}</p>
+                    </div>
+                    <a class="button" href="#deals" aria-label="Shop deal: ${deal.title}">Shop deal</a>
+                  </article>
+                `).join("")}
+              </div>
+            </div>
+          </section>
+        `;
+      }
+
+      function ArticleCard(article) {
+        return `
+          <article class="article-card">
+            <div class="article-media" style="--article-gradient: ${article.gradient};">
+              <span class="tag">${article.label}</span>
+            </div>
+            <div class="article-body">
+              <div class="article-meta">
+                <span>Editorial</span>
+                <span>5 min read</span>
+              </div>
+              <h3>${article.title}</h3>
+              <p class="muted">${article.copy}</p>
+              <a href="#editorial" aria-label="Read article: ${article.title}">Read article</a>
+            </div>
+          </article>
+        `;
+      }
+
+      function Editorial() {
+        return `
+          <section class="section container" id="editorial" aria-labelledby="editorial-title">
+            <div class="section-heading">
+              <div>
+                <p class="section-kicker">Editorial content</p>
+                <h2 id="editorial-title">Ideas for living well with less.</h2>
+              </div>
+              ${ButtonLink({ href: "#stories", label: "Browse all stories", variant: "button-secondary" })}
+            </div>
+            <div class="editorial-grid">
+              ${articles.map(ArticleCard).join("")}
+            </div>
+          </section>
+        `;
+      }
+
+      function Newsletter() {
+        return `
+          <section class="section container" aria-labelledby="newsletter-title">
+            <div class="newsletter">
+              <div>
+                <p class="section-kicker">Member preview</p>
+                <h2 id="newsletter-title">Get first access to drops and private deals.</h2>
+                <p class="muted">Join for weekly edits, restock alerts, and a welcome offer on your first order.</p>
+              </div>
+              <form class="newsletter-form" action="#" method="post">
+                <div class="field-group">
+                  <label for="email">Email address <span aria-hidden="true">*</span></label>
+                  <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required aria-describedby="email-help">
+                  <p class="muted" id="email-help">Required. We will only send product news and offers.</p>
+                </div>
+                <div class="form-actions">
+                  <button class="button" type="submit">Sign up for emails</button>
+                  <p class="muted" aria-live="polite" id="form-status"></p>
+                </div>
+              </form>
+            </div>
+          </section>
+        `;
+      }
+
+      function Footer() {
+        return `
+          <footer class="site-footer">
+            <div class="footer-inner">
+              <p><strong>North & Finch</strong> — modern retail for home, style, and daily rituals.</p>
+              <a href="#">Back to top</a>
+            </div>
+          </footer>
+        `;
+      }
+
+      function App() {
+        return `
+          ${Header()}
+          <main id="main-content">
+            ${Hero()}
+            ${FeaturedProducts()}
+            ${Deals()}
+            ${Editorial()}
+            ${Newsletter()}
+          </main>
+          ${Footer()}
+        `;
+      }
+
+      document.querySelector("#app").innerHTML = App();
+
+      document.querySelector(".newsletter-form").addEventListener("submit", (event) => {
+        event.preventDefault();
+        const form = event.currentTarget;
+        const email = form.elements.email;
+        const status = document.querySelector("#form-status");
+
+        if (!email.validity.valid) {
+          email.setAttribute("aria-invalid", "true");
+          status.textContent = "Enter a valid email address to sign up.";
+          email.focus();
+          return;
+        }
+
+        email.removeAttribute("aria-invalid");
+        status.textContent = "Thanks. You are on the list.";
+        form.reset();
+      });
+    </script>
+  </body>
+</html>
+

')

