        --shadow-card: 0 22px 50px #3d2c1c1f;
        --shadow-soft: 0 12px 28px #3d2c1c14;
        --radius-xl: 32px;
        --radius-lg: 22px;
        --radius-md: 16px;
        --max-width: 1180px;
        --space-page: clamp(1rem, 4vw, 2.5rem);
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        background:
          radial-gradient(circle at top left, #f8e8d9 0, transparent 26rem),
          linear-gradient(180deg, #fbfaf7 0%, #f7f2ea 100%);
        color: var(--color-ink);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      body,
      button,
      input {
        font: inherit;
      }

      a {
        color: inherit;
      }

      img,
      svg {
        max-width: 100%;
      }

      .skip-link {
        position: fixed;
        inset-block-start: 1rem;
        inset-inline-start: 1rem;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--color-ink);
        color: var(--color-surface);
        padding: 0.8rem 1rem;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      :focus-visible {
        outline: 3px solid var(--color-accent-strong);
        outline-offset: 4px;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 5;
        border-bottom: 1px solid #d9d0c4;
        background: #fbfaf7f2;
        backdrop-filter: blur(18px);
      }

      .header-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: min(100% - (var(--space-page) * 2), var(--max-width));
        margin-inline: auto;
        padding-block: 1rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        color: var(--color-ink);
        font-weight: 800;
        letter-spacing: -0.04em;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.45rem;
        height: 2.45rem;
        place-items: center;
        border-radius: 50%;
        background: var(--color-ink);
        color: var(--color-surface);
        font-size: 0.9rem;
        letter-spacing: 0.08em;
      }

      .nav-list,
      .utility-list {
        display: flex;
        align-items: center;
        gap: clamp(0.35rem, 1.4vw, 1rem);
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .nav-link,
      .utility-link {
        display: inline-flex;
        min-height: 2.75rem;
        align-items: center;
        border-radius: 999px;
        color: var(--color-muted);
        font-weight: 700;
        text-decoration: none;
      }

      .nav-link {
        padding-inline: 0.8rem;
      }

      .utility-link {
        border: 1px solid var(--color-border);
        background: transparent;
        padding-inline: 0.95rem;
        color: var(--color-ink);
        cursor: pointer;
      }

      .nav-link:hover,
      .utility-link:hover {
        color: var(--color-accent-strong);
        background: var(--color-accent-soft);
      }

      .container {
        width: min(100% - (var(--space-page) * 2), var(--max-width));
        margin-inline: auto;
      }

      .section {
        padding-block: clamp(3.75rem, 8vw, 6.75rem);
      }

      .section-heading {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-block-end: 1.5rem;
      }

      .section-kicker,
      .eyebrow {
        margin: 0 0 0.55rem;
        color: var(--color-accent-strong);
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        color: var(--color-ink);
        letter-spacing: -0.055em;
        line-height: 0.95;
      }

      h1 {
        max-width: 12ch;
        font-size: clamp(3.5rem, 11vw, 7.8rem);
      }

      h2 {
        font-size: clamp(2.1rem, 5vw, 4rem);
      }

      h3 {
        font-size: clamp(1.35rem, 2vw, 1.75rem);
      }

      p {
        margin-block: 0;
      }

      .muted {
        color: var(--color-muted);
      }

      .visually-hidden {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        clip-path: inset(50%);
        white-space: nowrap;
      }

      .button {
        display: inline-flex;
        min-height: 3rem;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        border: 1px solid var(--color-ink);
        border-radius: 999px;
        background: var(--color-ink);
        color: var(--color-surface);
        cursor: pointer;
        font-weight: 800;
        text-decoration: none;
      }

      .button:hover {
        background: var(--color-accent-strong);
        border-color: var(--color-accent-strong);
      }

      .button-secondary {
        background: transparent;
        color: var(--color-ink);
      }

      .button-secondary:hover {
        background: var(--color-ink);
        border-color: var(--color-ink);
        color: var(--color-surface);
      }

      .hero {
        padding-block: clamp(2rem, 6vw, 4.25rem) clamp(3.5rem, 8vw, 6rem);
      }

      .hero-grid {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(18rem, 0.72fr);
        gap: clamp(1rem, 4vw, 3rem);
        align-items: stretch;
      }

      .hero-copy {
        display: grid;
        align-content: center;
        min-height: 35rem;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-xl);
        background:
          linear-gradient(135deg, #fff8f1 0%, #f5e7d6 58%, #ead8c2 100%);
        padding: clamp(1.35rem, 5vw, 4.5rem);
        box-shadow: var(--shadow-soft);
      }

      .hero-copy .muted {
        max-width: 42rem;
        margin-block: 1.4rem 1.8rem;
        font-size: clamp(1.05rem, 2vw, 1.3rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.8rem;
      }

      .hero-actions .button {
        padding-inline: 1.25rem;
      }

      .hero-panel {
        display: grid;
        gap: 1rem;
      }

      .feature-card {
        position: relative;
        overflow: hidden;
        min-height: 24rem;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-xl);
        background:
          radial-gradient(circle at 70% 20%, #f6c58d 0 7rem, transparent 7.2rem),
          radial-gradient(circle at 18% 72%, #c7d7c6 0 9rem, transparent 9.2rem),
          linear-gradient(145deg, #ffffff 0%, #eee5da 100%);
        padding: 1.2rem;
        box-shadow: var(--shadow-card);
      }

      .product-visual {
        position: absolute;
        inset: 20% 12% auto;
        height: 13rem;
        border-radius: 42% 42% 30% 30%;
        background:
          linear-gradient(90deg, #1b1a18 0 7%, transparent 7% 93%, #1b1a18 93%),
          linear-gradient(135deg, #b97158, #ead0bd);
        box-shadow: 0 2rem 3rem #4c2b1f35;
      }

      .feature-card-content {
        position: relative;
        z-index: 1;
        display: flex;
        min-height: 100%;
        flex-direction: column;
        justify-content: space-between;
      }

      .tag {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        border: 1px solid var(--color-border);
        border-radius: 999px;
        background: var(--color-surface);
        color: var(--color-accent-strong);
        padding: 0.4rem 0.72rem;
        font-size: 0.82rem;
        font-weight: 850;
      }

      .mini-card {
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        padding: 1.35rem;
        box-shadow: var(--shadow-soft);
      }

      .stats {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 0.75rem;
        margin-block-start: 1rem;
      }

      .stat {
        border-radius: var(--radius-md);
        background: var(--color-surface-strong);
        padding: 1rem;
      }

      .stat strong {
        display: block;
        font-size: 1.45rem;
        letter-spacing: -0.04em;
      }

      .product-grid,
      .editorial-grid {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
      }

      .product-card,
      .article-card {
        display: flex;
        min-width: 0;
        flex-direction: column;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        box-shadow: var(--shadow-soft);
        overflow: hidden;
      }

      .product-media,
      .article-media {
        display: grid;
        min-height: 15rem;
        place-items: center;
        padding: 1rem;
      }

      .product-shape {
        width: min(13rem, 72%);
        aspect-ratio: 1;
        border-radius: 35%;
        background: var(--product-gradient);
        box-shadow: inset 0 -1rem 2rem #1b1a1814, 0 1rem 2.2rem #1b1a1817;
      }

      .product-card:nth-child(2) .product-shape {
        border-radius: 50% 50% 42% 42%;
      }

      .product-card:nth-child(3) .product-shape {
        border-radius: 22% 45% 28% 45%;
      }

      .product-body,
      .article-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        gap: 0.85rem;
        padding: 1.2rem;
      }

      .product-meta,
      .article-meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        color: var(--color-muted);
        font-size: 0.95rem;
        font-weight: 750;
      }

      .price-row {
        display: flex;
        align-items: baseline;
        gap: 0.5rem;
        margin-block-start: auto;
      }

      .price {
        font-size: 1.35rem;
        font-weight: 900;
      }

      .old-price {
        color: var(--color-muted);
        text-decoration: line-through;
      }

      .product-card .button {
        width: 100%;
        margin-block-start: 0.35rem;
      }

      .deals-band {
        display: grid;
        grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
        gap: 1rem;
        align-items: stretch;
        border-radius: var(--radius-xl);
      }

      .deal-hero,
      .deal-list {
        border: 1px solid var(--color-border);
        border-radius: var(--radius-xl);
        background: var(--color-ink);
        color: var(--color-surface);
        padding: clamp(1.35rem, 4vw, 2.5rem);
      }

      .deal-hero {
        display: grid;
        align-content: space-between;
        min-height: 24rem;
        background:
          radial-gradient(circle at 86% 16%, #c96d43 0 6.8rem, transparent 7rem),
          linear-gradient(135deg, #1b1a18 0%, #3d2b22 100%);
      }

      .deal-hero h2,
      .deal-list h3 {
        color: var(--color-surface);
      }

      .deal-hero .section-kicker,
      .deal-list .section-kicker {
        color: #ffd8c2;
      }

      .deal-hero .muted,
      .deal-list .muted {
        color: #eee3d7;
      }

      .deal-hero .button {
        width: fit-content;
        border-color: var(--color-surface);
        background: var(--color-surface);
        color: var(--color-ink);
        padding-inline: 1.25rem;
      }

      .deal-hero .button:hover {
        background: var(--color-accent-soft);
        color: var(--color-accent-strong);
      }

      .deal-list {
        display: grid;
        gap: 1rem;
        background: #2b271f;
      }

      .deal-item {
        display: grid;
        grid-template-columns: auto 1fr auto;
        gap: 1rem;
        align-items: center;
        border: 1px solid #746759;
        border-radius: var(--radius-lg);
        background: #fffaf00d;
        padding: 1rem;
      }

      .deal-percent {
        display: grid;
        width: 4rem;
        height: 4rem;
        place-items: center;
        border-radius: 50%;
        background: #ffd8c2;
        color: var(--color-accent-strong);
        font-weight: 950;
      }

      .deal-item .button {
        min-height: 2.75rem;
        border-color: #eee3d7;
        background: transparent;
        color: var(--color-surface);
        padding-inline: 1rem;
      }

      .article-media {
        align-items: end;
        min-height: 17rem;
        background: var(--article-gradient);
      }

      .article-card:first-child {
        grid-column: span 2;
      }

      .article-card:first-child .article-media {
        min-height: 22rem;
      }

      .article-card a {
        display: inline-flex;
        width: fit-content;
        margin-block-start: auto;
        color: var(--color-accent-strong);
        font-weight: 900;
        text-decoration-thickness: 0.12em;
        text-underline-offset: 0.22em;
      }

      .newsletter {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(18rem, 0.85fr);
        gap: 1rem;
        align-items: center;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-xl);
        background:
          radial-gradient(circle at 92% 20%, #f6c58d 0 8rem, transparent 8.2rem),
          var(--color-surface);
        padding: clamp(1.35rem, 5vw, 3rem);
        box-shadow: var(--shadow-soft);
      }

      .newsletter-form {
        display: grid;
        gap: 0.75rem;
      }

      .field-group {
        display: grid;
        gap: 0.35rem;
      }

      .field-group label {
        font-weight: 850;
      }

      .field-group input {
        min-height: 3.2rem;
        width: 100%;
        border: 1px solid var(--color-border);
        border-radius: 999px;
        background: #fff;
        color: var(--color-ink);
        padding-inline: 1rem;
      }

      .field-group input:invalid:not(:placeholder-shown) {
        border-color: var(--color-accent-strong);
      }

      .newsletter-form .button {
        padding-inline: 1.2rem;
      }

      .form-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      .site-footer {
        border-top: 1px solid var(--color-border);
        background: var(--color-ink);
        color: var(--color-surface);
      }

      .footer-inner {
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 1rem;
        align-items: center;
        width: min(100% - (var(--space-page) * 2), var(--max-width));
        margin-inline: auto;
        padding-block: 1.5rem;
      }

      .footer-inner a {
        color: var(--color-surface);
        font-weight: 800;
      }

      @media (max-width: 900px) {
        .header-inner,
        .nav-list,
        .utility-list {
          flex-wrap: wrap;
        }

        .site-nav {
          order: 3;
          width: 100%;
        }

        .hero-grid,
        .deals-band,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .hero-copy {
          min-height: 28rem;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .article-card:first-child {
          grid-column: span 2;
        }
      }

      @media (max-width: 620px) {
        .section-heading,
        .footer-inner,
        .deal-item {
          align-items: start;
          grid-template-columns: 1fr;
        }

        .section-heading {
          display: grid;
        }

        .product-grid,
        .editorial-grid,
        .stats {
          grid-template-columns: 1fr;
        }

        .article-card:first-child {
          grid-column: auto;
        }

        .hero-copy {
          min-height: auto;
        }

        .deal-item .button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .button,
        .tag,
        .utility-link,
        .product-card,
        .article-card,
        .mini-card,
        .deal-hero,
        .deal-list,
        .newsletter,
        .hero-copy {
          border-color: ButtonBorder;
        }

        .button,
        .skip-link {
          background: ButtonText;
          color: Canvas;
        }

        .button-secondary {
          background: Canvas;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const products = [
        {
          name: "Curve Lounge Chair",
          category: "Home",
          price: "$248",
          oldPrice: "$310",
          badge: "Best seller",
          gradient: "linear-gradient(135deg, #91533e 0%, #e7b59f 100%)"
        },
        {
          name: "Everyday Linen Set",
          category: "Bedroom",
          price: "$96",
          oldPrice: "$128",
          badge: "Organic cotton",
          gradient: "linear-gradient(135deg, #d9c7ac 0%, #ffffff 100%)"
        },
        {
          name: "Modular Weekender Tote",
          category: "Travel",
          price: "$132",
          oldPrice: "$165",
          badge: "New color",
          gradient: "linear-gradient(135deg, #263c32 0%, #a8c3a8 100%)"
        }
      ];

      const deals = [
        {
          percent: "30%",
          title: "Tabletop refresh",
          copy: "Stoneware, glassware, and serving pieces for spring gatherings."
        },
        {
          percent: "25%",
          title: "Workday staples",
          copy: "Tailored layers, bags, and desk accessories built for daily use."
        },
        {
          percent: "20%",
          title: "Wellness edit",
          copy: "Soft robes, clean candles, and recovery essentials for slower nights."
        }
      ];

      const articles = [
        {
          label: "Design guide",
          title: "How to build a warmer room with fewer pieces",
          copy: "Our stylists share a simple formula for texture, tone, and negative space.",
          gradient: "linear-gradient(135deg, #efe2d0 0%, #b87b5f 100%)"
        },
        {
          label: "Behind the brand",
          title: "Meet the makers shaping our ceramic collection",
          copy: "A look inside small-batch studios and the craft behind each glaze.",
          gradient: "linear-gradient(135deg, #e9efe5 0%, #6c856e 100%)"
        },
        {
          label: "Trend report",
          title: "Utility details are changing weekend style",
          copy: "Pockets, weatherproof finishes, and softer structure are leading the season.",
          gradient: "linear-gradient(135deg, #f3e3c9 0%, #9b6415 100%)"
        }
      ];

      function ButtonLink({ href, label, variant = "" }) {
        return `<a class="button ${variant}" href="${href}">${label}</a>`;
      }

      function Header() {
        const navItems = [
          { label: "Home", href: "#main-content" },
          { label: "New Arrivals", href: "#featured-products" },
          { label: "Deals", href: "#deals" },
          { label: "Stories", href: "#editorial" }
        ];
        return `
          <header class="site-header">
            <div class="header-inner">
              <a class="brand" href="#" aria-label="North & Finch home">
                <span class="brand-mark" aria-hidden="true">N&F</span>
                <span>North & Finch</span>
              </a>
              <nav class="site-nav" aria-label="Primary navigation">
                <ul class="nav-list">
                  ${navItems.map((item) => `
                    <li><a class="nav-link" href="${item.href}">${item.label}</a></li>
                  `).join("")}
                </ul>
              </nav>
              <nav aria-label="Shopping links">
                <ul class="utility-list">
                  <li><a class="utility-link" href="#featured-products">Shop</a></li>
                  <li>
                    <button class="utility-link cart-button" type="button" aria-describedby="cart-status">
                      Cart (<span id="cart-count">0</span>)
                    </button>
                  </li>
                </ul>
              </nav>
              <span class="visually-hidden" id="cart-status" aria-live="polite">Your cart is empty.</span>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero container" aria-labelledby="hero-title">
            <div class="hero-grid">
              <div class="hero-copy">
                <p class="eyebrow">Spring collection 2026</p>
                <h1 id="hero-title">Design-led essentials for everyday living.</h1>
                <p class="muted">
                  Shop considered home goods, wardrobe staples, and travel-ready accessories
                  from a retail brand focused on longevity, comfort, and calm.
                </p>
                <div class="hero-actions">
                  ${ButtonLink({ href: "#featured-products", label: "Shop featured products" })}
                  ${ButtonLink({ href: "#editorial", label: "Read the edit", variant: "button-secondary" })}
                </div>
              </div>
              <div class="hero-panel" aria-label="Collection highlights">
                <article class="feature-card">
                  <div class="product-visual" aria-hidden="true"></div>
                  <div class="feature-card-content">
                    <span class="tag">Limited capsule</span>
                    <div>
                      <h2>Quiet luxury, lower impact.</h2>
                      <p class="muted">Natural fibers, modular silhouettes, and packaging designed for reuse.</p>
                    </div>
                  </div>
                </article>
                <aside class="mini-card" aria-label="Store benefits">
                  <p class="eyebrow">Why shoppers return</p>
                  <div class="stats">
                    <div class="stat"><strong>4.9</strong><span class="muted">Average rating</span></div>
                    <div class="stat"><strong>2-day</strong><span class="muted">Express delivery</span></div>
                    <div class="stat"><strong>365</strong><span class="muted">Day returns</span></div>
                  </div>
                </aside>
              </div>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        return `
          <article class="product-card">
            <div class="product-media" style="background: ${product.gradient};">
              <div class="product-shape" style="--product-gradient: ${product.gradient};" aria-hidden="true"></div>
            </div>
            <div class="product-body">
              <div class="product-meta">
                <span>${product.category}</span>
                <span class="tag">${product.badge}</span>
              </div>
              <h3>${product.name}</h3>
              <p class="muted">Refined proportions, durable materials, and a soft modern finish.</p>
              <div class="price-row">
                <span class="price">${product.price}</span>
                <span class="old-price">${product.oldPrice}</span>
              </div>
              <button class="button add-to-cart" type="button" aria-label="Add to cart: ${product.name}">Add to cart</button>
            </div>
          </article>
        `;
      }

      function FeaturedProducts() {
        return `
          <section class="section container" id="featured-products" aria-labelledby="featured-title">
